const generateProbeRequest = (Atrributes, id)=>{
    const attributes = Atrributes;
    const request='https://ripe-13prsouz.uc.gateway.dev/measurements?/probe_id='+id;
    const genReq=()=>{
        for (let i =0; i< attributes.length;i++){
            switch (attributes[i].key){
                case 'group':
                    request = request+ '&group_by='+atrributes[i].value;
                break;
                case 'year':
                    request = request+ '&year='+atrributes[i].value;
                break;
                case 'month':
                    request = request+ '&month='+atrributes[i].value;
                break;
                case 'measurement':
                    request = request+ '&measurement_id='+atrributes[i].value;
                break;
            }
        }
    }

    return genReq();
}
export default generateProbeRequest;
